// Fase 5C.6 test tooling only (never imported by src/): independent implementations of the
// CFDI seal used to cross-check ORBIT's node:crypto signer.
// - OpenSSL command line (`openssl dgst -sha256 -sign/-verify`, PKCS#1 v1.5 by default).
// - Microsoft .NET Framework on Windows (CNG: RSACng.SignData/VerifyData with
//   RSASignaturePadding.Pkcs1), through Windows PowerShell.
// Keys are SYNTHETIC and generated by the test. OpenSSL needs the key in a file: it is
// written to a fresh directory under the OS temporary folder and deleted right after. The
// .NET path receives everything through stdin. Nothing is written inside the repository.
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const run = (command, args, options = {}) =>
  spawnSync(command, args, {
    encoding: "buffer",
    windowsHide: true,
    ...options,
  });

export function opensslVersion() {
  const result = run("openssl", ["version"]);
  return result.status === 0 ? result.stdout.toString("utf8").trim() : null;
}

export function dotnetVersion() {
  if (process.platform !== "win32") return null;
  const result = run("powershell.exe", [
    "-NoProfile",
    "-NonInteractive",
    "-Command",
    "[System.Runtime.InteropServices.RuntimeInformation]::FrameworkDescription",
  ]);
  return result.status === 0 ? result.stdout.toString("utf8").trim() : null;
}

/**
 * Signs each message with OpenSSL (SHA-256, default RSA padding = PKCS#1 v1.5) and verifies
 * each given signature with the certificate's public key, with the default padding and with
 * PSS. Returns Base64 signatures and verification results.
 * @param {Buffer} pkcs8Der unencrypted synthetic PKCS#8
 * @param {Buffer} certificateDer
 * @param {Buffer[]} messages
 * @param {Buffer[]} signatures signatures to verify (same order as messages)
 */
export function opensslSignAndVerify(
  pkcs8Der,
  certificateDer,
  messages,
  signatures,
) {
  const directory = mkdtempSync(join(tmpdir(), "orbit-seal-openssl-"));
  try {
    const key = join(directory, "synthetic.pem");
    // PEM armor assembled at runtime so the repository never contains a key header.
    const label = ["PRIVATE", "KEY"].join(" ");
    const pem =
      `-----BEGIN ${label}-----\n` +
      pkcs8Der.toString("base64").replace(/.{1,64}/g, "$&\n") +
      `-----END ${label}-----\n`;
    writeFileSync(key, pem, { mode: 0o600 });
    const cert = join(directory, "certificate.cer");
    writeFileSync(cert, certificateDer);
    const publicKey = join(directory, "public.pem");
    execFileSync(
      "openssl",
      [
        "x509",
        "-inform",
        "DER",
        "-in",
        cert,
        "-pubkey",
        "-noout",
        "-out",
        publicKey,
      ],
      { windowsHide: true },
    );
    return messages.map((message, index) => {
      const data = join(directory, `message-${index}.bin`);
      const signatureFile = join(directory, `signature-${index}.bin`);
      writeFileSync(data, message);
      execFileSync(
        "openssl",
        ["dgst", "-sha256", "-sign", key, "-out", signatureFile, data],
        { windowsHide: true },
      );
      const signature = readFileSync(signatureFile).toString("base64");
      writeFileSync(signatureFile, signatures[index]);
      const verify = (extra) =>
        run("openssl", [
          "dgst",
          "-sha256",
          "-verify",
          publicKey,
          ...extra,
          "-signature",
          signatureFile,
          data,
        ]).status === 0;
      return {
        signature,
        verifiesPkcs1: verify([]),
        verifiesPss: verify(["-sigopt", "rsa_padding_mode:pss"]),
      };
    });
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
}

const dotnetScript = `
$ErrorActionPreference = 'Stop'
$inputJson = [Console]::In.ReadToEnd() | ConvertFrom-Json
$cng = [System.Security.Cryptography.CngKey]::Import([Convert]::FromBase64String($inputJson.pkcs8), [System.Security.Cryptography.CngKeyBlobFormat]::Pkcs8PrivateBlob)
$private = New-Object System.Security.Cryptography.RSACng($cng)
$certificate = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2(,[Convert]::FromBase64String($inputJson.certificate))
$public = [System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($certificate)
$sha256 = [System.Security.Cryptography.HashAlgorithmName]::SHA256
$out = @()
for ($i = 0; $i -lt $inputJson.messages.Count; $i++) {
  $data = [Convert]::FromBase64String($inputJson.messages[$i])
  $given = [Convert]::FromBase64String($inputJson.signatures[$i])
  $own = $private.SignData($data, $sha256, [System.Security.Cryptography.RSASignaturePadding]::Pkcs1)
  $out += [pscustomobject]@{
    signature = [Convert]::ToBase64String($own)
    verifiesPkcs1 = $public.VerifyData($data, $given, $sha256, [System.Security.Cryptography.RSASignaturePadding]::Pkcs1)
    verifiesPss = $public.VerifyData($data, $given, $sha256, [System.Security.Cryptography.RSASignaturePadding]::Pss)
  }
}
$cng.Dispose()
ConvertTo-Json -InputObject @($out) -Compress
`;

/** Same as opensslSignAndVerify with Windows CNG (.NET Framework, Windows PowerShell). */
export function dotnetSignAndVerify(
  pkcs8Der,
  certificateDer,
  messages,
  signatures,
) {
  const result = run(
    "powershell.exe",
    ["-NoProfile", "-NonInteractive", "-Command", dotnetScript],
    {
      input: Buffer.from(
        JSON.stringify({
          pkcs8: pkcs8Der.toString("base64"),
          certificate: certificateDer.toString("base64"),
          messages: messages.map((m) => m.toString("base64")),
          signatures: signatures.map((s) => Buffer.from(s).toString("base64")),
        }),
        "utf8",
      ),
    },
  );
  if (result.status !== 0) throw new Error("DOTNET_FAILED");
  return JSON.parse(result.stdout.toString("utf8"));
}
